'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),crypto=require('node:crypto'),M=require('../model.js'),UI=require('../c2.js'),{fixture}=require('./dom_fixture.cjs');
const root=path.resolve(__dirname,'..'),read=n=>JSON.parse(fs.readFileSync(path.join(root,'data',n),'utf8')),schema=read('method.json'),mapping=read('mapping.json'),compat=read('analysis.compat.json'),m=M.build(schema,mapping),paper={short_name:'HarnessVLN',version:'arXiv 2609.15195v3'};let count=0;const test=(name,fn)=>{fn();count++;console.log('PASS '+name);};
function start(options={}){const f=fixture(options);assert.deepEqual(f.errors,[]);f.c2.open('harnessvln',f.app.getContext());return f;}
test('frozen mapping and compatibility adapter match the upstream-verified hash seal',()=>{const seal=read('UPSTREAM-VERIFICATION.json');for(const local of ['method.json','mapping.json','analysis.compat.json','ledger.json'])assert.equal(crypto.createHash('sha256').update(fs.readFileSync(path.join(root,'data',local))).digest('hex'),seal[local]);assert.deepEqual(compat.answers.map(a=>[a.nodeId,a.state,a.answer]),mapping.answers.map(a=>[a.nodeId,a.state,a.answer]));});
test('59 original labels, parents and order are unchanged; 13 instances resolve to originals',()=>{assert.equal(schema.nodes.length,59);assert.equal(m.nodes.size,72);for(const n of schema.nodes){const x=m.nodes.get(n.id);assert.equal(x.label,n.labelOriginal);assert.equal(x.parent,n.parentId);assert.equal(x.order,n.order);}for(const n of mapping.expandedNodes){assert(m.nodes.get(n.nodeId).isInstance);assert(schema.nodes.some(x=>x.id===n.repeatOfSchemaNode));}assert.deepEqual(M.validate(m),[]);});
test('all six unresolved questions coexist with answers; missing source array remains',()=>{assert.equal(m.questions.length,6);assert.equal(m.answers.size,47);assert(m.questions.some(q=>q.nodeId==='method.module1.how'&&q.state==='source_missing'&&q.sourceLocators.length===0));assert(m.questions.some(q=>m.answers.has(q.nodeId)));assert.equal(mapping.existingStageStateMutation,false);});
test('the original asymmetric contribution questions and multiline Overview leaves remain intact',()=>{const contribution1=M.children(m,'introduction.pipeline.contribution1').map(n=>n.label),contribution2=M.children(m,'introduction.pipeline.contribution2').map(n=>n.label);assert.notDeepEqual(contribution1,contribution2);assert(m.nodes.get('method.overview.steps').label.includes('\n'));assert.equal(M.children(m,'method.overview.steps').length,0);});
test('controlled overview retains five sections and selected path with explicit folded counts',()=>{for(const id of m.nodes.keys()){const s=M.locate(m,M.initial(m),id),g=M.overviewLayout(m,s);assert.equal(new Set(g.nodes.map(n=>n.id)).size,g.nodes.length);for(const section of M.SECTIONS)assert(g.nodes.some(n=>n.id===section));for(const a of M.ancestors(m,id))assert(g.nodes.some(n=>n.id===a));assert.equal(g.totalCount,72);assert.equal(g.foldedCount,72-g.visibleCount);assert(g.visibleCount<30);}});
test('every node is directly locatable with legal full ancestry and selected visibility',()=>{for(const id of m.nodes.keys()){const s=M.locate(m,M.initial(m),id);assert.equal(s.selected,id);assert(M.ancestors(m,id).includes(s.focus));const scene=M.layout(m,s,820);assert(scene.nodes.some(n=>n.id===id));}});
test('pagination exposes all direct children, never silently picks representatives',()=>{for(const id of m.nodes.keys()){let s={...M.initial(m),focus:id};const b=M.branch(m,s),seen=[];for(let page=0;page<=b.maxPage;page++){s=M.reduce(m,s,{type:'page',page});seen.push(...M.branch(m,s).items.map(n=>n.id));}assert.deepEqual(seen,M.children(m,id).map(n=>n.id));}});
test('jumping to module 4 then returning reveals its parent page',()=>{let s=M.locate(m,M.initial(m),'method.module4');s=M.reduce(m,s,{type:'back'});assert.equal(s.focus,'method');assert(M.branch(m,s).items.some(n=>n.id==='method.module4'));});
test('all focus layouts are bounded and nonoverlapping at 390, 580, 820 and 1160 CSS pixels',()=>{for(const width of [390,580,820,1160])for(const id of m.nodes.keys()){let s=M.locate(m,M.initial(m),id);const b=M.branch(m,s);for(let page=0;page<=b.maxPage;page++){s=M.reduce(m,s,{type:'page',page});const scene=M.layout(m,s,width);for(const n of scene.nodes){assert(n.x>=0&&n.y>=0);assert(n.x+n.w<=scene.width+.01,n.id);assert(n.y+n.h<=scene.height+.01,n.id);assert(n.w>=144);}for(let i=0;i<scene.nodes.length;i++)for(let j=i+1;j<scene.nodes.length;j++){const a=scene.nodes[i],b=scene.nodes[j];assert(a.x+a.w<=b.x||b.x+b.w<=a.x||a.y+a.h<=b.y||b.y+b.h<=a.y,'overlap '+a.id+' '+b.id);}}}});
test('long labels use explicit ellipsis with complete original text retained separately',()=>{const long=[...m.nodes.values()].sort((a,b)=>b.label.length-a.label.length)[0],preview=M.previewLabel(long.label,218);assert(preview.truncated);assert(preview.text.endsWith('…'));const s=M.locate(m,M.initial(m),long.id);const html=UI.renderHtml(m,s,paper,820);assert(html.includes('展开完整原题'));assert(html.includes(UI.pathText(m,long.id).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')));});
test('other 38 papers never inherit HarnessVLN answers or instances',()=>{const catalog=JSON.parse(fs.readFileSync(path.join(root,'../data/catalog.json')));for(const p of catalog.papers.filter(p=>p.canonical_id!=='harnessvln')){const other=M.build(schema,mapping,p.canonical_id);assert.equal(other.nodes.size,59);assert.equal(other.answers.size,0);assert.equal(other.questions.length,0);assert.equal(other.mapping,null);}});
test('search reaches all 72 original questions and supports a genuine empty result',()=>{assert.equal(M.search(m).length,72);for(const id of m.nodes.keys())assert(M.search(m,id).some(n=>n.id===id));assert.equal(M.search(m,'__missing_047899_node__').length,0);});
test('C2 initial DOM retains five global branches, root focus tree and closed evidence drawer',()=>{const f=start();assert.equal(f.$$('#c2-tree-workspace').length,1);assert.equal(f.$$('.c2-global-branch').length,5);assert(f.$('.c2-canvas'));assert(f.$('.c2-links').querySelectorAll('path').length>0);assert.equal(f.$('#c2-overlay'),null);assert.equal(f.c2.getState().focus,M.ROOT);});
test('selection retains global highlight and opens evidence only when requested',()=>{const f=start();f.c2.dispatch({type:'select',id:'method.module1.why'});assert.equal(f.$('#c2-overlay'),null);assert(f.$('.c2-mini-current').textContent.includes('为什么能work'));f.click('[data-c2="evidence"]');assert(f.$('#c2-drawer-body').textContent.includes('读者解释'));assert(f.$('#c2-drawer-body').textContent.includes('证据边界'));assert(f.$('#c2-tree-workspace').getAttribute('inert')!==null);});
test('source drawer opens exact provided fixed-version locations',()=>{const f=start();f.c2.dispatch({type:'select',id:'method.module1.why'});f.click('[data-c2="evidence"]');f.click('[data-tab="sources"]');assert(f.$('#c2-drawer-body').querySelectorAll('a').some(a=>(a.getAttribute('href')||'').startsWith('https://arxiv.org')));assert(f.$('#c2-drawer-body').textContent.includes('2609.15195v3'));});
test('six unresolved questions, including empty code locators, are visible in one complete view',()=>{const f=start();f.click('[data-c2="unresolved"]');assert.equal(f.$('#c2-drawer-body').querySelectorAll('.c2-question').length,6);assert(f.$('#c2-drawer-body').textContent.includes('源码尚未阅读'));for(const q of m.questions)assert(f.$('#c2-drawer-body').textContent.includes(q.question));});
test('Escape closes drawer back to the selected tree node and does not clear the base paper',()=>{const f=start();f.c2.dispatch({type:'select',id:'method.module1.why'});const base=f.app.getState().paper;f.click('[data-c2="evidence"]');f.$('#c2-drawer-back').emit('keydown',{key:'Escape'});assert.equal(f.c2.getState().drawer,null);assert.equal(f.app.getState().paper,base);assert.equal(f.document.activeElement.id,'c2-node-method_module1_why');});
test('repeated node and evidence clicks neither grow history nor reset scroll',()=>{const f=start();f.click('[data-c2="evidence"]');f.$('#c2-drawer-body').scrollTop=411;const length=f.historyStack.length;f.c2.dispatch({type:'drawer',drawer:'evidence'});assert.equal(f.historyStack.length,length);assert.equal(f.$('#c2-drawer-body').scrollTop,411);});
test('changing evidence tabs or selected nodes resets drawer scroll to the top',()=>{const f=start();f.click('[data-c2="evidence"]');f.$('#c2-drawer-body').scrollTop=510;f.c2.dispatch({type:'tab',tab:'sources'});assert.equal(f.$('#c2-drawer-body').scrollTop,0);f.c2.dispatch({type:'drawer',drawer:'evidence',id:'method.module4.how'});assert.equal(f.$('#c2-drawer-body').scrollTop,0);assert(f.$('#c2-drawer-body').textContent.includes('可靠'));assert(f.$('#c2-drawer-body').textContent.includes('回退'));});
test('browser back/forward restores focus, selection and drawer state',()=>{const f=start();const original=JSON.stringify(f.c2.getState());f.c2.dispatch({type:'enter',id:'method.module4'});f.c2.dispatch({type:'drawer',drawer:'evidence',id:'method.module4.how'});f.back();assert.equal(f.c2.getState().drawer,null);assert.equal(f.c2.getState().focus,'method.module4');f.back();assert.equal(JSON.stringify(f.c2.getState()),original);f.forward();assert.equal(f.c2.getState().focus,'method.module4');});
test('complete current-layer directory is stable in URL history and exposes every child',()=>{const f=start();f.click('[data-c2="layer-directory"]');assert.equal(f.$('#c2-drawer-body').querySelectorAll('.c2-directory-row').length,M.children(m,M.ROOT).length);assert.equal(f.c2.getState().directoryScope,M.ROOT);f.c2.dispatch({type:'close'});f.back();assert.equal(f.c2.getState().directoryScope,M.ROOT);assert(f.$('#c2-drawer-title').textContent.includes('本层'));});
test('directory query, no result and clear preserve the 72-node source',()=>{const f=start();f.$('#c2-search').value='__missing_047899_node__';f.$('#c2-search-form').emit('submit');assert(f.$('#c2-drawer-body').textContent.includes('没有匹配节点'));f.click('[data-c2="clear-search"]');assert.equal(f.$('#c2-drawer-body').querySelectorAll('.c2-directory-row').length,72);assert.equal(f.c2.getModel().nodes.size,72);});
test('keyboard supports overview Enter, evidence tab arrows and Home/End',()=>{const f=start();const overview=f.$('.c2-global-branch[data-id="experiments"]');assert.equal(overview.tagName,'BUTTON');overview.emit('click');assert.equal(f.c2.getState().focus,'experiments');f.click('[data-c2="evidence"]');f.$('#c2-tab-answer').emit('keydown',{key:'ArrowRight'});assert.equal(f.c2.getState().drawerTab,'sources');f.$('#c2-tab-sources').emit('keydown',{key:'End'});assert.equal(f.c2.getState().drawerTab,'scope');f.$('#c2-tab-scope').emit('keydown',{key:'Home'});assert.equal(f.c2.getState().drawerTab,'answer');});
test('double-tree → HarnessVLN C2 → return preserves query, pages, selected paper and scroll',()=>{const f=fixture();f.app.dispatch({type:'search',query:'Harness'});f.app.dispatch({type:'paper',id:'harnessvln'});f.app.dispatch({type:'tab',tab:'analysis'});f.$('#catalog-list').scrollTop=184;f.$('#paper-body').scrollTop=72;const before=f.app.getContext();f.click('[data-open-analysis="harnessvln"]');assert(f.c2.isOpen());f.c2.dispatch({type:'enter',id:'experiments'});f.click('[data-c2="return"]');assert(!f.c2.isOpen());assert.equal(JSON.stringify(f.app.getState()),JSON.stringify(before.state));assert.equal(f.$('#catalog-list').scrollTop,184);assert.equal(f.$('#paper-body').scrollTop,72);});
test('both literature and challenge paths survive the C2 round trip',()=>{const f=fixture();for(const key of ['l','c']){const p=f.app.model.trees[key].paths.find(p=>p.paperId==='harnessvln');f.app.dispatch({type:'path',key,id:p.id});const state=JSON.stringify(f.app.getState());f.c2.open('harnessvln',f.app.getContext());f.c2.returnToTrees();assert.equal(JSON.stringify(f.app.getState()),state);}});
test('direct analysis deep link restores without losing source boundaries',()=>{const f=fixture({url:'https://example.test/local-only/#analysis='+encodeURIComponent(JSON.stringify({paperId:'harnessvln',focus:'method.module4',selected:'method.module4.how',drawer:'evidence'}))});assert(f.c2.isOpen());assert(f.$('#c2-drawer-body').textContent.includes('可靠'));assert(f.$('#c2-drawer-body').textContent.includes('2.5'));});
test('pending paper has honest empty analysis UI and no scientific answers',()=>{const f=fixture();f.c2.open('navharness',f.app.getContext());assert(f.$('.c2-analysis-pending').textContent.includes('尚未建立'));f.click('[data-c2="evidence"]');assert(f.$('#c2-drawer-body').textContent.includes('本篇解析待建立'));assert.equal(f.c2.getModel().answers.size,0);});
test('390px model uses stacked readable cards and retains all catalogue nodes',()=>{const f=start({mobile:true,width:390,height:844});assert(f.c2.isOpen());const scene=M.layout(m,M.initial(m),340);assert(scene.vertical);assert(scene.nodes.every(n=>n.w>=250||n.depth===1));f.click('[data-c2="directory"]');assert.equal(f.$('#c2-drawer-body').querySelectorAll('.c2-directory-row').length,72);});
test('script-free alternative contains all nodes, all answers, all six unresolved and all 39 papers',()=>{const html=fs.readFileSync(path.join(root,'reading.html'),'utf8');for(const n of m.nodes.values())assert(html.includes('id="node-'+n.id+'"'));for(const q of m.questions)assert(html.includes(q.question.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')));assert.equal((html.match(/id="paper-/g)||[]).length,39);assert(!/<script\b/.test(html));assert(html.includes('相关源码尚未阅读'));});
test('render contains no fit-to-all text scaling and no automatic reading-stage promotion',()=>{const js=fs.readFileSync(path.join(root,'c2.js'),'utf8'),css=fs.readFileSync(path.join(root,'c2.css'),'utf8');assert(!js.includes('scale('));assert(!css.includes('transform:scale'));assert(css.includes('font:600 17px'));assert(js.includes('Stage 未改'));assert(!js.includes('全文精读完成'));});
test('mobile keeps five global branches and focus simultaneously without shrinking focus text',()=>{const f=start({mobile:true,width:390,height:844});assert.equal(f.$$('.c2-global-branch').length,5);assert(f.$('.c2-canvas'));f.click('.c2-global-branch[data-id="method"]');f.c2.dispatch({type:'enter',id:'method.module3'});assert.equal(f.c2.getState().focus,'method.module3');assert.equal(f.$$('.c2-global-branch').length,5);assert(f.$('.c2-canvas'));const css=fs.readFileSync(path.join(root,'c2.css'),'utf8');assert(css.includes('#c2-app .c2-mobile-switch{display:none}'));assert(css.includes('font:600 17px'));});
test('P1: every selected node is present after adaptive focus at 390, 580, 719, 720 and 820px',()=>{for(const width of [390,580,719,720,820])for(const id of m.nodes.keys()){let s={...M.initial(m),selected:id};s=M.forWidth(m,s,width);assert(M.layout(m,s,width).nodes.some(n=>n.id===id),'missing '+id+' at '+width);}const f=start({mobile:true,width:390,height:844});assert.equal(f.c2.getState().focus,M.ROOT);for(const id of M.SECTIONS)assert(f.$('.c2-global-branch[data-id="'+id+'"]'));});
test('P1: overview hit rectangles never overlap and exceed desktop/mobile target minimum',()=>{for(const id of m.nodes.keys()){const g=M.overviewLayout(m,M.locate(m,M.initial(m),id));for(const n of g.nodes){assert(n.h>=40);assert(n.w>=100);assert(n.h*600/g.width>=44);}for(let i=0;i<g.nodes.length;i++)for(let j=i+1;j<g.nodes.length;j++){const a=g.nodes[i],b=g.nodes[j];assert(a.x+a.w<=b.x||b.x+b.w<=a.x||a.y+a.h/2<=b.y-b.h/2||b.y+b.h/2<=a.y-a.h/2,'overlap '+a.id+' '+b.id);}}});
test('P2: opening and closing evidence preserves user scroll away from selected node',()=>{const f=start();f.c2.dispatch({type:'select',id:'method.overview.task'});f.$('#c2-focus-region').scrollTop=140;f.click('[data-c2="evidence"]');assert.equal(f.$('#c2-focus-region').scrollTop,140);f.c2.dispatch({type:'close'});assert.equal(f.$('#c2-focus-region').scrollTop,140);});
test('P2: browser back reopening a drawer restores its per-node/per-tab reading position',()=>{const f=start();f.c2.dispatch({type:'drawer',drawer:'evidence',id:'limitation',tab:'sources'});f.$('#c2-drawer-body').scrollTop=320;f.c2.dispatch({type:'close'});f.back();assert.equal(f.c2.getState().drawer,'evidence');assert.equal(f.c2.getState().drawerTab,'sources');assert.equal(f.$('#c2-drawer-body').scrollTop,320);});
test('P1: mobile controlled overview uses readable 360px hierarchy with 44px nonoverlapping hit rows',()=>{for(const id of m.nodes.keys()){const g=M.overviewLayout(m,M.locate(m,M.initial(m),id),true);assert.equal(g.width,360);for(const n of g.nodes){assert.equal(n.h,44);assert(n.w>=250);assert(n.x+n.w<=360);}for(let i=1;i<g.nodes.length;i++)assert(g.nodes[i].y-g.nodes[i-1].y>=54);}const f=start({mobile:true,width:390,height:844});f.click('[data-pane="overview"]');assert.equal(f.$$('.c2-global-branch').length,5);assert(f.$('.c2-canvas'));const css=fs.readFileSync(path.join(root,'c2.css'),'utf8');assert(css.includes('#c2-app .c2-mobile-switch{display:none}'));});
test('P1: width adaptation relocates a legacy deep selection and preserves open drawer and active tab',()=>{const original={...M.initial(m),focus:'method',selected:'method.module1.why',drawer:'evidence',drawerTab:'sources'},adapted=M.forWidth(m,original,390);assert.notEqual(adapted,original);assert.equal(adapted.focus,'method.module1');assert.equal(adapted.drawer,'evidence');assert.equal(adapted.drawerTab,'sources');assert.equal(adapted.selected,original.selected);assert(M.layout(m,adapted,390).nodes.some(n=>n.id===original.selected));const f=fixture({url:'https://example.test/local-only/#analysis='+encodeURIComponent(JSON.stringify(original))});assert(f.c2.isOpen());assert.equal(f.c2.getState().focus,'method.module1');assert.equal(f.c2.getState().selected,'method.module1.why');assert.equal(f.c2.getState().drawer,'evidence');assert.equal(f.c2.getState().drawerTab,'sources');assert.equal(f.document.activeElement.id,'c2-drawer-back');});
test('P2: deep links and browser-back dialogs focus an active control inside the modal',()=>{const f=fixture({url:'https://example.test/local-only/#analysis='+encodeURIComponent(JSON.stringify({paperId:'harnessvln',focus:'method.module4',selected:'method.module4.how',drawer:'evidence'}))});assert.equal(f.document.activeElement.id,'c2-drawer-back');f.c2.dispatch({type:'close'});f.back();assert.equal(f.c2.getState().drawer,'evidence');assert.equal(f.document.activeElement.id,'c2-drawer-back');});
console.log('\n'+count+' C2 checks passed. Model/in-memory DOM and deterministic geometry only. Real browser and actual viewport screenshots NOT RUN.');fs.writeFileSync(path.join(__dirname,'report.json'),JSON.stringify({status:'passed',checks:count,templateNodes:59,instances:13,answers:47,unresolvedQuestions:6,scope:'Pure model, deterministic layout geometry, source integrity and in-memory DOM',realBrowser:'NOT_RUN',realViewportScreenshots:'NOT_RUN',publication:'NOT_RUN'},null,2)+'\n');
